From b8fb2168442992b3d1ad398b6ab1f3ba31c04de4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:35:53 +0100
Subject: [PATCH] activitymanager: show the switcher for Switch to
 Next/Previous Activity

Unlike "Walk through activities", the Switch to Next and Previous
Activity shortcuts never showed the switcher. Now they show it while
their keys are held, listing activities in the fixed order they use.

BUG: 484584
---
 .../activitymanager/sortedactivitiesmodel.cpp | 17 ++++++++++++
 .../activitymanager/sortedactivitiesmodel.h   |  3 +++
 imports/activitymanager/switcherbackend.cpp   | 26 +++++++++++++++++++
 imports/activitymanager/switcherbackend.h     |  4 +++
 4 files changed, 50 insertions(+)

diff --git a/imports/activitymanager/sortedactivitiesmodel.cpp b/imports/activitymanager/sortedactivitiesmodel.cpp
index f200d0655d..0937dfdaef 100644
--- a/imports/activitymanager/sortedactivitiesmodel.cpp
+++ b/imports/activitymanager/sortedactivitiesmodel.cpp
@@ -305,6 +305,14 @@ void SortedActivitiesModel::setInhibitUpdates(bool inhibitUpdates)
     }
 }

+void SortedActivitiesModel::setFixedOrder(bool fixedOrder)
+{
+    if (m_fixedOrder != fixedOrder) {
+        m_fixedOrder = fixedOrder;
+        sort(0, fixedOrder ? Qt::AscendingOrder : Qt::DescendingOrder);
+    }
+}
+
 uint SortedActivitiesModel::lastUsedTime(const QString &activity) const
 {
     if (m_activities->currentActivity() == activity) {
@@ -323,6 +331,15 @@ bool SortedActivitiesModel::lessThan(const QModelIndex &sourceLeft, const QModel
     const auto activityLeft = sourceModel()->data(sourceLeft, KActivities::ActivitiesModel::ActivityId).toString();
     const auto activityRight = sourceModel()->data(sourceRight, KActivities::ActivitiesModel::ActivityId).toString();

+    if (m_fixedOrder) {
+        // The order kactivitymanagerd uses to switch to the next and previous activity
+        const auto nameLeft = sourceModel()->data(sourceLeft, KActivities::ActivitiesModel::ActivityName).toString();
+        const auto nameRight = sourceModel()->data(sourceRight, KActivities::ActivitiesModel::ActivityName).toString();
+        const auto comp = QString::compare(nameLeft, nameRight, Qt::CaseInsensitive);
+
+        return comp < 0 || (comp == 0 && activityLeft < activityRight);
+    }
+
     const auto timeLeft = lastUsedTime(activityLeft);
     const auto timeRight = lastUsedTime(activityRight);

diff --git a/imports/activitymanager/sortedactivitiesmodel.h b/imports/activitymanager/sortedactivitiesmodel.h
index 82d9a809d7..c8f5bbb97c 100644
--- a/imports/activitymanager/sortedactivitiesmodel.h
+++ b/imports/activitymanager/sortedactivitiesmodel.h
@@ -38,6 +38,8 @@ public:

     bool inhibitUpdates() const;

+    void setFixedOrder(bool fixedOrder);
+
 protected:
     uint lastUsedTime(const QString &activity) const;
     bool lessThan(const QModelIndex &source_left, const QModelIndex &source_right) const override;
@@ -66,6 +68,7 @@ Q_SIGNALS:

 private:
     bool m_inhibitUpdates;
+    bool m_fixedOrder = false;

     QString m_previousActivity;

diff --git a/imports/activitymanager/switcherbackend.cpp b/imports/activitymanager/switcherbackend.cpp
index 3744bc1fe2..e75b7818ec 100644
--- a/imports/activitymanager/switcherbackend.cpp
+++ b/imports/activitymanager/switcherbackend.cpp
@@ -35,6 +35,9 @@

 static const char *s_action_name_next_activity = "next activity";
 static const char *s_action_name_previous_activity = "previous activity";
+// Registered by plasmashell, these go through the activities in a fixed order
+static const char *s_action_name_switch_to_next_activity = "switch to next activity";
+static const char *s_action_name_switch_to_previous_activity = "switch to previous activity";

 namespace
 {
@@ -184,6 +187,8 @@ SwitcherBackend::SwitcherBackend(QObject *parent)
                      Qt::META | Qt::SHIFT | Qt::Key_A,
                      &SwitcherBackend::keybdSwitchToPreviousActivity);

+    connect(KGlobalAccel::self(), &KGlobalAccel::globalShortcutActiveChanged, this, &SwitcherBackend::onGlobalShortcutActiveChanged);
+
     connect(this, &SwitcherBackend::shouldShowSwitcherChanged, m_runningActivitiesModel, &SortedActivitiesModel::setInhibitUpdates);

     m_modKeyPollingTimer.setInterval(100);
@@ -253,6 +258,24 @@ void SwitcherBackend::keybdSwitchedToAnotherActivity()
     QTimer::singleShot(100, this, &SwitcherBackend::showActivitySwitcherIfNeeded);
 }

+bool SwitcherBackend::isFixedOrderAction(const QAction *action) const
+{
+    return action
+        && (action->objectName() == QLatin1String(s_action_name_switch_to_next_activity)
+            || action->objectName() == QLatin1String(s_action_name_switch_to_previous_activity));
+}
+
+void SwitcherBackend::onGlobalShortcutActiveChanged(QAction *action, bool active)
+{
+    if (!active || !isFixedOrderAction(action)) {
+        return;
+    }
+
+    m_actionShortcut[action->objectName()] = KGlobalAccel::self()->shortcut(action).value(0);
+    m_lastInvokedAction = action;
+    QTimer::singleShot(100, this, &SwitcherBackend::showActivitySwitcherIfNeeded);
+}
+
 void SwitcherBackend::showActivitySwitcherIfNeeded()
 {
     if (!m_lastInvokedAction || m_dropModeActive) {
@@ -329,10 +352,13 @@ void SwitcherBackend::setShouldShowSwitcher(bool shouldShowSwitcher)
     m_shouldShowSwitcher = shouldShowSwitcher;

     if (m_shouldShowSwitcher) {
+        m_runningActivitiesModel->setFixedOrder(isFixedOrderAction(m_lastInvokedAction));
+
         // TODO: We really should NOT do this by polling
         m_modKeyPollingTimer.start();
     } else {
         m_modKeyPollingTimer.stop();
+        m_runningActivitiesModel->setFixedOrder(false);

         // We might have an unprocessed onCurrentActivityChanged
         onCurrentActivityChanged(m_activities.currentActivity());
diff --git a/imports/activitymanager/switcherbackend.h b/imports/activitymanager/switcherbackend.h
index 76900de797..8b13c1fd81 100644
--- a/imports/activitymanager/switcherbackend.h
+++ b/imports/activitymanager/switcherbackend.h
@@ -86,6 +86,8 @@ private:

     void switchToActivity(Direction i);

+    bool isFixedOrderAction(const QAction *action) const;
+
 private Q_SLOTS:
     void keybdSwitchToNextActivity();
     void keybdSwitchToPreviousActivity();
@@ -93,6 +95,8 @@ private Q_SLOTS:

     void showActivitySwitcherIfNeeded();

+    void onGlobalShortcutActiveChanged(QAction *action, bool active);
+
     void onCurrentActivityChanged(const QString &id);

 private:
